# Generated by Cursor (TDD plan item 1: symbols and currency)
"""Scan for symbol and currency spans; emit (rule_id, start_index, span, path_str)."""

import re

# Currency: £ or $ followed by digits (with optional commas/decimals)
CURRENCY_GBP_RE = re.compile(r"£[\d,]+(?:\.[\d]+)?")
CURRENCY_USD_RE = re.compile(r"\$[\d,]+(?:\.[\d]+)?")
# Section ref §1519 (must run before standalone §)
SECTION_REF_RE = re.compile(r"§\d+")
SECTION_RE = re.compile(r"§")
COPYRIGHT_RE = re.compile(r"©")
# Standalone £ (not followed by digit or comma)
POUND_STANDALONE_RE = re.compile(r"£(?![\d,])")


def scan_turn_symbols(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """
    Scan text for symbol and currency spans; emit (rule_id, start_index, span, path_str).

    Order: currency (so £40 is currency not symbol_pound), section ref, section, copyright, pound standalone.
    """
    result: list[tuple[str, int, str, str]] = []
    for m in CURRENCY_GBP_RE.finditer(text):
        result.append(("currency", m.start(), m.group(0), path_str))
    for m in CURRENCY_USD_RE.finditer(text):
        result.append(("currency", m.start(), m.group(0), path_str))
    currency_starts = {m.start() for m in CURRENCY_GBP_RE.finditer(text)}
    for m in SECTION_REF_RE.finditer(text):
        result.append(("symbol_section_ref", m.start(), m.group(0), path_str))
    for m in SECTION_RE.finditer(text):
        result.append(("symbol_section", m.start(), m.group(0), path_str))
    for m in COPYRIGHT_RE.finditer(text):
        result.append(("symbol_copyright", m.start(), m.group(0), path_str))
    for m in POUND_STANDALONE_RE.finditer(text):
        if m.start() not in currency_starts:
            result.append(("symbol_pound", m.start(), m.group(0), path_str))
    return result
